    var u=String(links.get(i).attr("href"))
    if(seen[u]){continue}
    seen[u]=1
    var title=""
    var cell=null
    var p=links.get(i)
    while(p!=null){
      var cn=String(p.classNames ? p.classNames() : "")
      if(cn.indexOf("playlist-hover-wrap")>=0){cell=p;break}
      p=p.parent()
    }
    if(cell){
      var h4=cell.selectFirst("h4.video-title")
      title=h4?h4.text().trim():""
    }
    if(!title){title="P"+(out.length+1)}
    out.push({n:title,u:u})
  }
  return out
}

function H1CONTENT(java,source,result,baseUrl){
  var d=org.jsoup.Jsoup.parse(String(result))
  var vp=d.selectFirst("video#player")
  if(!vp){return ""}
  var srcs=vp.select("source")
  var pick=null;var curQ="720"
