  try{res=java.appCache!==undefined?java.ajaxAll(urls):java.ajaxAll(urls)}catch(e){H1L("H1L: 测速失败 "+e);return}
  var ms=[];var okAny=false
  for(var i=0;i<ds.length;i++){
